SET hive.exec.dynamic.partition=true;
SET hive.exec.dynamic.partition.mode=nonstrict;
CREATE TABLE a_agg_daily_sales (sale_date DATE, ss_store_sk INT, category STRING, price_band STRING,
  tickets BIGINT, quantity BIGINT, net_paid DECIMAL(17,2), net_profit DECIMAL(17,2)) PARTITIONED BY (d_year INT) STORED AS PARQUET;
INSERT OVERWRITE TABLE a_agg_daily_sales PARTITION (d_year)
SELECT s.sale_date, s.ss_store_sk, i.category, i.price_band, count(DISTINCT s.ss_ticket_number), sum(s.quantity), sum(s.net_paid), sum(s.net_profit), s.d_year
FROM a_stg_store_sales s JOIN a_stg_item i ON i.i_item_sk = s.ss_item_sk
GROUP BY s.sale_date, s.ss_store_sk, i.category, i.price_band, s.d_year;
SELECT * FROM a_agg_daily_sales

CREATE TABLE a_agg_region_month (region STRING, d_year INT, d_moy INT, tickets BIGINT, net_paid DECIMAL(17,2)) STORED AS PARQUET;
INSERT OVERWRITE TABLE a_agg_region_month
SELECT st.region, s.d_year, s.d_moy, count(DISTINCT s.ss_ticket_number), sum(s.net_paid)
FROM a_stg_store_sales s JOIN a_stg_store st ON st.s_store_sk = s.ss_store_sk
GROUP BY st.region, s.d_year, s.d_moy;
SELECT * FROM a_agg_region_month ORDER BY region, d_year, d_moy

CREATE TABLE a_agg_category_year (d_year INT, category STRING, net_paid DECIMAL(17,2), net_profit DECIMAL(17,2), tickets BIGINT) STORED AS PARQUET;
INSERT OVERWRITE TABLE a_agg_category_year
SELECT d_year, category, sum(net_paid), sum(net_profit), sum(tickets) FROM a_agg_daily_sales GROUP BY d_year, category;
SELECT * FROM a_agg_category_year ORDER BY d_year, category

CREATE TABLE b25_by_store (ss_store_sk INT, paid DECIMAL(17,2)) STORED AS PARQUET;
CREATE TABLE b25_by_item (ss_item_sk INT, qty BIGINT) STORED AS PARQUET;
FROM (SELECT * FROM store_sales WHERE ss_sold_date_sk BETWEEN 2451545 AND 2451560 AND ss_item_sk <= 40) s
INSERT OVERWRITE TABLE b25_by_store SELECT ss_store_sk, sum(ss_net_paid) GROUP BY ss_store_sk
INSERT OVERWRITE TABLE b25_by_item SELECT ss_item_sk, sum(ss_quantity) GROUP BY ss_item_sk;
SELECT 'store' AS src, ss_store_sk AS k, cast(paid AS double) AS v FROM b25_by_store UNION ALL SELECT 'item', ss_item_sk, cast(qty AS double) FROM b25_by_item ORDER BY src, k

SET hive.exec.dynamic.partition.mode=nonstrict;
CREATE TABLE b34_mixed (ss_item_sk INT, q BIGINT) PARTITIONED BY (d_year INT, d_moy INT) STORED AS PARQUET;
INSERT OVERWRITE TABLE b34_mixed PARTITION (d_year = 2000, d_moy)
SELECT ss_item_sk, sum(ss_quantity), d.d_moy FROM store_sales ss JOIN date_dim d ON d.d_date_sk = ss.ss_sold_date_sk WHERE d.d_year = 2000 AND d.d_moy = 12 AND ss_item_sk <= 30 GROUP BY ss_item_sk, d.d_moy;
INSERT OVERWRITE TABLE b34_mixed PARTITION (d_year = 2001, d_moy)
SELECT ss_item_sk, sum(ss_quantity), d.d_moy FROM store_sales ss JOIN date_dim d ON d.d_date_sk = ss.ss_sold_date_sk WHERE d.d_year = 2001 AND d.d_moy <= 2 AND ss_item_sk <= 30 GROUP BY ss_item_sk, d.d_moy;
INSERT OVERWRITE TABLE b34_mixed PARTITION (d_year = 2001, d_moy)
SELECT ss_item_sk, sum(ss_quantity), d.d_moy FROM store_sales ss JOIN date_dim d ON d.d_date_sk = ss.ss_sold_date_sk WHERE d.d_year = 2001 AND d.d_moy = 2 AND ss_item_sk <= 30 GROUP BY ss_item_sk, d.d_moy;
SELECT * FROM b34_mixed ORDER BY d_year, d_moy, ss_item_sk

SET hivevar:run_year=2001;
SET hivevar:min_item=30;
CREATE TABLE b64_param (ss_item_sk INT, n BIGINT) STORED AS PARQUET;
INSERT OVERWRITE TABLE b64_param SELECT ss_item_sk, count(*) FROM store_sales ss JOIN date_dim d ON d.d_date_sk = ss.ss_sold_date_sk WHERE d.d_year = ${hivevar:run_year} AND ss_item_sk <= ${hivevar:min_item} GROUP BY ss_item_sk;
SELECT * FROM b64_param ORDER BY ss_item_sk

ADD JAR hdfs:///libs/retail-udfs-2.3.jar;
CREATE TEMPORARY FUNCTION normalize_sku AS 'com.retailco.hive.NormalizeSku';
SELECT normalize_sku(i_item_id) AS sku, count(*) AS n FROM store_sales ss JOIN item i ON i.i_item_sk = ss.ss_item_sk WHERE ss_sold_date_sk BETWEEN 2451545 AND 2451560 GROUP BY normalize_sku(i_item_id) ORDER BY sku

ADD JAR hdfs:///libs/retail-udfs-2.3.jar;
CREATE TEMPORARY FUNCTION weighted_median AS 'com.retailco.hive.WeightedMedianUDAF';
CREATE TABLE b40_store_median STORED AS PARQUET AS SELECT ss_store_sk, weighted_median(ss_net_paid, ss_quantity) AS wm FROM store_sales WHERE ss_sold_date_sk BETWEEN 2451545 AND 2451560 GROUP BY ss_store_sk;
SELECT * FROM b40_store_median ORDER BY ss_store_sk

CREATE TABLE b44_raw (id INT, v STRING) ROW FORMAT DELIMITED FIELDS TERMINATED BY ',' STORED AS TEXTFILE;
LOAD DATA INPATH '/data/landing/raw_2026-01-01.csv' INTO TABLE b44_raw;
SELECT count(*) AS n FROM b44_raw

CREATE TABLE b68_daily (ss_store_sk INT, paid DECIMAL(17,2), load_ts TIMESTAMP) STORED AS PARQUET;
INSERT OVERWRITE TABLE b68_daily SELECT ss_store_sk, sum(ss_net_paid), current_timestamp() FROM store_sales WHERE ss_sold_date_sk BETWEEN 2451545 AND 2451560 GROUP BY ss_store_sk;
SELECT * FROM b68_daily ORDER BY ss_store_sk
